"""Product analytics dashboard: conversion statistics over customer sessions."""


def _converted_count(events):
    return sum(1 for e in events if e["converted"] is True)


def conversion_rate(events):
    """The conversion rate of a list of sessions. See SPEC.md section 1."""
    return _converted_count(events) / len(events) if events else 0.0


def pooled_conversion_rate(groups):
    """The pooled conversion rate across groups of sessions. See SPEC.md section 2."""
    total = sum(len(events) for events in groups.values())
    return sum(_converted_count(events) for events in groups.values()) / total if total else 0.0


def conversions_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    return sum(daily_counts[-days:]) if days > 0 else 0


def conversion_rate_by_group(groups):
    """The conversion rate of each group. See SPEC.md section 9."""
    return {
        name: conversion_rate(groups[name]) if groups[name] else None
        for name in sorted(groups)
    }


def longest_conversion_streak(daily_counts):
    """Longest run of days with converted sessions. See SPEC.md section 10."""
    best = cur = 0
    for c in daily_counts:
        if c > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""Product analytics dashboard: conversion statistics over customer sessions."""


def parse_session_log(lines):
    """Parse log lines into sessions. See SPEC.md section 4."""
    flags = {"1": True, "0": False, "": None}
    out = []
    for line_number, line in enumerate(lines, start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected three fields")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: day must be an integer") from exc
        if flag not in flags:
            raise ValueError(f"line {line_number}: converted must be 1, 0, or empty")
        out.append({"id": id_, "day": day, "converted": flags[flag]})
    return out


def dedupe_sessions(events):
    """Remove duplicate sessions. See SPEC.md section 5."""
    by_id = {e["id"]: e for e in events}
    return sorted(by_id.values(), key=lambda e: (e["day"], e["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Daily counts of converted sessions. See SPEC.md section 6."""
    counts = [0] * max(0, end_day - start_day + 1)
    for e in events:
        day = e["day"]
        if start_day <= day <= end_day and e["converted"] is True:
            counts[day - start_day] += 1
    return counts

